from scipy.optimize import least_squares
t=df['t'].values; x=df['x'].values; v=df['v'].values; y=df['dv_dt'].values
den=np.sum((y-y.mean())**2)
cands={
 't':lambda p: t,'t*v':lambda p: t*v,'t*x':lambda p: t*x,'t*v^2':lambda p:t*v**2,'t*x*v':lambda p:t*x*v,'t*x^2':lambda p:t*x**2,
 'sin(t)':lambda p:np.sin(p[4]*t),'exp(-p t)':lambda p:np.exp(-p[4]*t),'t*exp(-p x)':lambda p:t*np.exp(-p[4]*x),
 'v':lambda p:v,'x':lambda p:x,'x*v':lambda p:x*v,'v*exp(-p x^2)':lambda p:v*np.exp(-p[4]*x**2),
 'x^2 v':lambda p:x**2*v,'v^2':lambda p:v**2,'exp(-p v)':lambda p:np.exp(-p[4]*v),'sin(p v)':lambda p:np.sin(p[4]*v),'cos(p t)':lambda p:np.cos(p[4]*t)
}
for k,g in cands.items():
    best=None
    for s in [0.3,1,3]:
        def f(p):
            q=p.copy()
            G=g(q)
            M=np.column_stack([np.exp(-q[0]*x**2), (t**2/(1+q[1]*t**2))*v**3, (1/(1+q[2]*x))/v, G])
            cc=np.linalg.lstsq(M,y,rcond=None)[0]
            return y-M@cc
        p0=np.array([1,0.5,0.1,0.1,s])
        try:
            r=least_squares(lambda p: f(np.r_[p,0])[:0] if False else f(p),p0)
            val=np.sum(r.fun**2)/den
        except Exception as e:
            val=np.nan
        if best is None or val<best[0]: best=(val,r.x if val==val else None)
    print(k,best)
